import { test, expect } from '@playwright/test';

test.describe('No Results Found Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display "No results found" when API returns an empty list', async ({ page }) => {
    // Set up intercept for empty response
    await page.route('**/api/search', (route) => {
      route.abort('failed');
    });

    // Set up intercept for successful response with empty list
    await page.route('**/api/search', (route) => {
      route.continue({
        status: 200,
        body: JSON.stringify([])
      });
    });

    // Verify search input is visible
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Fill search input with query
    await searchInput.fill('nonexistent query');

    // Verify results container is empty
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeEmpty();

    // Verify 'No results found' message is displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();

    // Verify message has correct styling
    await expect(noResultsMessage).toHaveClass(/alert-message/);

    // Verify search button is still visible and enabled
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();
    await expect(searchButton).toBeEnabled();

    // Verify no results message is visible when page is reloaded
    await page.reload();
    await expect(noResultsMessage).toBeVisible();
  });

  test('should handle empty list gracefully and not display error message', async ({ page }) => {
    // Set up intercept for successful response with empty list
    await page.route('**/api/search', (route) => {
      route.continue({
        status: 200,
        body: JSON.stringify([])
      });
    });

    // Verify search input is visible
    const searchInput = page.getByLabel('Search');
    await expect(searchInput).toBeVisible();

    // Fill search input with query
    await searchInput.fill('nonexistent query');

    // Verify results container is empty
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeEmpty();

    // Verify no results message is displayed
    const noResultsMessage = page.getByText('No results found');
    await expect(noResultsMessage).not.toBeVisible();

    // Verify error message is not displayed
    const errorMessage = page.getByText('Error');
    await expect(errorMessage).not.toBeVisible();

    // Verify search button is still visible and enabled
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();
    await expect(searchButton).toBeEnabled();

    // Verify page content is still visible
    const pageContent = page.getByTestId('page-content');
    await expect(pageContent).toBeVisible();
  });
});
